<template>
  <div class="full-width" v-if="!displayTable">
    <q-markup-table class="full-width">
      <thead>
        <tr class="highlighted-back">
          <th>
            <template v-if="isFormBuilderMode">
              No columns found. Please contact system administrator.
            </template>
            <template v-else>
              No columns found. Please go to
              <span class="cursor-pointer link" @click="routeToTableTraining"
                >table training view</span
              >.
            </template>
          </th>
        </tr>
      </thead>
    </q-markup-table>
  </div>

  <div :class="'full-width ' + fieldName" v-if="displayTable">
    <div class="full-width">
      <q-table
        class="full-width"
        :id="'table_' + fieldName"
        row-key="id"
        flat
        :no-data-label="$t('no_record_found')"
        hide-bottom
        :rows="tableRows"
        :columns="tableColumns"
        :rows-per-page-options="[0]"
        :table-header-style="{ backgroundColor: 'var(--fb-bg-tertiary)' }"
        style="
          overflow: auto;
          height: auto;
          min-height: 180px;
          max-height: 500px;
        "
      >
        <template v-slot:header="props">
          <q-tr :props="props" class="bg-grey-3" v-if="isFormBuilderMode">
            <draggable
              v-model="props.cols"
              class="dragArea"
              item-key="name"
              :group="{ name: 'formbuilder', pull: false, put: true }"
              :sort="true"
              ghost-class="sortable__ghost"
              @change="itemDraggedComplete"
            >
              <template v-for="(element, index) in props.cols" :key="index">
                <q-td
                  :id="'col_' + element.col_id"
                  :class="
                    (element.tr_ocr_model_id ? 'text-primary' : '') +
                    ' ' +
                    getColumnClass(element.label)
                  "
                  class="text-center"
                >
                  <q-btn
                    flat
                    :label="element.label"
                    @click="markTableColumns($event, element.col_id)"
                  />
                </q-td>
              </template>
            </draggable>
          </q-tr>

          <q-tr :props="props" class="bg-grey-3" v-else>
            <q-td v-if="!isReadOnly">
              <q-icon
                flat
                dense
                size="22px"
                color="primary"
                class="cursor-pointer"
                @click="addRow"
                v-if="!isFormBuilderMode"
              >
                <q-tooltip>{{ $t('add_row') }}</q-tooltip>
                <Icon icon="mdi:table-row-plus-after" width="22" height="22" />
              </q-icon>
            </q-td>
            <template
              v-for="(item, index) in props.cols"
              :key="index"
              :props="props"
            >
              <q-td
                :id="'col_' + item.col_id"
                class="text-center"
                :class="getColumnClass(item.label)"
              >
                <span> {{ item.label }} </span>
              </q-td>
            </template>
          </q-tr>
        </template>

        <template v-slot:body="props">
          <q-tr :props="props" :id="getRowIdPrefix() + props.key">
            <q-td v-if="!isReadOnly" data-name="actions" class="no-wrap-text">
              <q-btn
                tabindex="0"
                flat
                color="primary"
                @click="removeRow(props.rowIndex, props.key)"
                icon="close"
                class="padding-left-right-2"
              />
              <q-btn
                tabindex="0"
                flat
                color="primary"
                @click="copyRow(props.rowIndex)"
                icon="content_copy"
                class="padding-left-right-2"
              />
            </q-td>

            <template v-for="col in props.cols" :key="col.name" :props="props">
              <q-td
                :data-name="col.name"
                :data-type="col.col_type"
                :data-input-class="
                  tableRowsObj[props.key]['columns'][col.name].col_class
                "
              >
                <div
                  :id="
                    tableRowsObj[props.key]['columns'][col.name].col_class +
                    '_parent'
                  "
                  class="autocomplete"
                  role="combobox"
                  aria-autocomplete="list"
                  aria-controls="suggestions"
                  aria-expanded="false"
                >
                  <q-input
                    outlined
                    v-if="col.col_type.toLowerCase() != 'boolean'"
                    :disable="isReadOnly"
                    :class="
                      'input-text-28px ' +
                      tableRowsObj[props.key]['columns'][col.name].col_class +
                      ' ' +
                      getInputTextElementBorder(
                        tableRowsObj[props.key]['columns'][col.name].is_valid,
                      )
                    "
                    @change="inputValueChanges(col.name, props.key)"
                    v-model="
                      tableRowsObj[props.key]['columns'][col.name]
                        .formatted_value
                    "
                    autocomplete="off"
                    :data-column-name="col.name"
                  />

                  <autocomplete
                    v-if="
                      hasListOfValuesForAnyColumn() &&
                      lov_columns_mapping[col.name]
                    "
                    :input_class="
                      tableRowsObj[props.key]['columns'][col.name].col_class
                    "
                    :parent_id="
                      tableRowsObj[props.key]['columns'][col.name].col_class +
                      '_parent'
                    "
                    :options="getListOfValues(lov_columns_mapping[col.name])"
                  />

                  <q-checkbox
                    child_type="checkbox"
                    :disable="isReadOnly"
                    tabindex="0"
                    v-if="col.col_type.toLowerCase() == 'boolean'"
                    :class="
                      tableRowsObj[props.key]['columns'][col.name].col_class +
                      ' ' +
                      getCheckBoxElementBorder(
                        tableRowsObj[props.key]['columns'][col.name].is_valid,
                      )
                    "
                    @focus="focusEvent"
                    @update:model-value="
                      (val: any) => {
                        checkboxUpdateForColumn(col.name, props.key, val);
                      }
                    "
                    v-model="
                      tableRowsObj[props.key]['columns'][col.name]
                        .formatted_value
                    "
                    size="30px"
                    color="grey-6"
                  />
                </div>
              </q-td>
            </template>
          </q-tr>
        </template>
      </q-table>
    </div>
  </div>
</template>

<script lang="ts">
import { uid } from 'quasar';
import { storeToRefs } from 'pinia';

import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import helperUtil from 'src/utils/helperUtil';
import keyboardUtil from 'src/utils/keyboard';
import documentUtil from 'src/utils/documentUtil';
import { isObjectEmtpy } from 'src/utils/general';
import { VueDraggableNext } from 'vue-draggable-next';
import resizableGridUtil from 'src/utils/resizableGridUtil';
import {
  useFormBuilderStore,
  useFieldValuesSettingsStore,
} from 'src/store/main';
import autocomplete from 'src/formBuilder/form_elements/components/autocomplete.vue';
import { formBuilderInputTypes } from 'src/formBuilder/formBuilderConstants';

export default defineComponent({
  name: 'ExtractedTable',
  components: {
    
    autocomplete,
    draggable: VueDraggableNext,
  },
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  emits: [
    'inputClicked',
    'updateModel',
    'inputValueChanges',
    'markTableColumns',
  ],
  mixins: [helperUtil, keyboardUtil, documentUtil, resizableGridUtil],
  beforeRouteLeave: function (to: any, from: any, next: any) {
    this.destoryAndRest(this.tableId);
    next();
  },
  data() {
    return {
      displayTable: ref(false),
      savedColumnsMap: new Map(),
    };
  },
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  mounted: function () {
    this.init();
    document.addEventListener('prepare_rows', this.prepareRows);
  },
  unmounted: function () {
    document.removeEventListener('prepare_rows', this.prepareRows);
    if (!this.fieldName) {
      return;
    }
    let fieldEl: HTMLElement | null = document!.querySelector(
      '.' + this.fieldName,
    );
    if (fieldEl) {
      fieldEl.removeEventListener(
        'focus_first_row_column',
        this.focusFirstRowColumn,
      );
      fieldEl.removeEventListener('trigger_add_row', this.triggerAddRow);
      fieldEl.removeEventListener('keydown', this.handleKeyDown);
    }

    if (!this.tableRowsObj) {
      return;
    }
    for (let [index, row] of Object.entries(this.tableRowsObj)) {
      this.removeEventOnRow(row);
    }
  },
  methods: {
    itemDraggedComplete(e: any) {
      if (e.moved) {
        const oldItem = this.tableColumns[e.moved.oldIndex];
        this.tableColumns.splice(e.moved.oldIndex, 1);
        this.tableColumns.splice(e.moved.newIndex, 0, oldItem);

        const tempOldItem =
          this.formBuilderConfigModel[this.fieldName].columns[e.moved.oldIndex];

        this.formBuilderConfigModel[this.fieldName].columns.splice(
          e.moved.oldIndex,
          1,
        );
        this.formBuilderConfigModel[this.fieldName].columns.splice(
          e.moved.newIndex,
          0,
          tempOldItem,
        );
      }
    },
    async init() {
      if (this.isFormBuilderMode) {
        return;
      }

      await this.prepareColumns();
      this.prepareRows();
      this.hasTable();
      this.initEventsOnMount();
      this.resetAndReInitColumnResize('table_' + this.fieldName);
    },

    hasListOfValuesForAnyColumn() {
      if (this.isFormBuilderMode) {
        return false;
      }
      if (isObjectEmtpy(this.lov_columns_mapping)) {
        return false;
      }
      return true;
    },
    getColumnClass(columnStr: string) {
      const stringObj = columnStr.split(' ');
      if (stringObj.length == 2) {
        return stringObj[1].length == 1 ? 'no-wrap-text' : '';
      }

      return '';
    },
    getLablel(columnStr: string) {
      return this.stringReplaceWithString(columnStr, '_', ' ');
    },
    addItemToColumnList(
      colObj: any,
      coord: any,
      tr_ocr_model_id: string,
      run_script_on_change: boolean,
    ) {
      const column = Object.assign(
        {},
        {
          name: colObj.column_name,
          label: this.getLablel(colObj.title),
          field: colObj.column_name,
          col_id: colObj.id,
          col_type: colObj.column_type,
          tr_ocr_model_id: tr_ocr_model_id,
        },
      );

      this.tableColumns.push(column);
      this.column_properties_map[colObj.column_name] = column;

      this.formBuilderConfigModel[this.fieldName].columns.push({
        coords: coord,
        col_id: colObj.id,
        name: colObj.column_name,
        column_type: colObj.column_type,
        list_of_values: this.lov_columns_mapping[colObj.column_name],
        run_script_on_change: run_script_on_change,
        tr_ocr_model_id: tr_ocr_model_id,
      });
    },
    async prepareColumns() {
      this.tableColumns = [];
      const tempColumMap = new Map();
      this.column_properties_map = {} as dynamicObj;
      const savedColumns = this.formBuilderConfigModel[this.fieldName].columns;

      await this.getDocumentTables(this.docType);

      if (!this.documentTables.hasOwnProperty(this.fieldName)) {
        return;
      }

      for (const column of this.documentTables[this.fieldName]) {
        tempColumMap.set(column.column_name, column);
      }

      // clear old Saved columns
      this.formBuilderConfigModel[this.fieldName].columns = [];
      let coord = [];
      let tr_ocr_model_id = '';
      let run_script_on_change = false;

      // insert the values in sort order
      for (const col of savedColumns) {
        this.savedColumnsMap.set(col.name, col);

        if (!tempColumMap.has(col.name)) {
          continue;
        }

        if (col.list_of_values) {
          this.lov_columns_mapping[col.name] = col.list_of_values;
        }

        coord = col.coords ? col.coords : [];
        tr_ocr_model_id = col.tr_ocr_model_id ? col.tr_ocr_model_id : '';
        run_script_on_change = col.run_script_on_change
          ? col.run_script_on_change
          : false;

        this.addItemToColumnList(
          tempColumMap.get(col.name),
          coord,
          tr_ocr_model_id,
          run_script_on_change,
        );

        tempColumMap.delete(col.name);
      }

      // add remaining columns who was not available before
      for (const [key, columnObj] of tempColumMap) {
        this.addItemToColumnList(columnObj, [], '', false);
      }
    },
    prepareRows() {
      this.tableRows = [];
      this.tableRowsObj = [];

      if (
        this.isFormBuilderMode ||
        !this.formBuilderModel.hasOwnProperty(this.fieldName)
      ) {
        return;
      }

      Array.from(this.formBuilderModel[this.fieldName].rows).forEach(
        (row: any, index: any) => {
          let newRow = [] as any;
          this.tableRowsObj[row.id] = [];
          this.tableRowsObj[row.id].columns = [];
          let columnsObj = [] as any;

          let existingColumns = JSON.parse(
            JSON.stringify(this.column_properties_map),
          );
          // Store extra column for remove button
          newRow['id'] = row.id;

          for (const column of row.columns) {
            newRow[column.name] = column.formatted_value;
            column.col_type = this.getColumnType(column.name);

            columnsObj.push(this.columnModel(column));
            this.addRowToTableRowObj(row.id, column.id, column);

            if (existingColumns.hasOwnProperty(column.name)) {
              delete existingColumns[column.name];
            }
          }

          // Add Missing Columns From existing tables
          for (let [index, column] of Object.entries(existingColumns)) {
            const col = this.getNewColumnObj(column);
            newRow[col.name] = col.formatted_value;
            columnsObj.push(this.columnModel(col));
            this.addRowToTableRowObj(row.id, col.id, col);
          }

          this.formBuilderModel[this.fieldName].rows[index]['columns'] =
            columnsObj;

          this.tableRows.push(newRow);
        },
      );

      if (this.tableRows.length == 0) {
        this.addRow();
      }
    },

    async addRow() {
      let rowId = uid();
      let newRow = [] as any;
      let columnsObj = [] as any;
      this.tableRowsObj[rowId] = [];
      this.tableRowsObj[rowId].columns = [];

      // Store extra column for remove button
      newRow['id'] = rowId;

      for (let [index, column] of Object.entries(this.tableColumns)) {
        const col = this.getNewColumnObj(column);
        newRow[col.name] = col.formatted_value;
        this.addRowToTableRowObj(rowId, col.id, col);
        columnsObj.push(this.columnModel(column));
      }

      this.tableRows.push(newRow);
      this.formBuilderModel[this.fieldName].rows.push(
        Object.assign({}, { id: rowId, columns: columnsObj }),
      );

      await this.$nextTick();
      this.addEventOnRowColumns(rowId, this.tableRowsObj[rowId]);
    },

    getColumnType(column_name: string) {
      let column_type = formBuilderInputTypes.TEXT_INPUT;

      if (this.column_properties_map.hasOwnProperty(column_name)) {
        const item = this.column_properties_map[column_name];
        column_type = item.col_type;
      }

      return column_type;
    },

    getNewColumnObj(col: any) {
      col.col_type = this.getColumnType(col.name);
      return Object.assign(col, {
        col_type: col.col_type,
        id: uid(),
        formatted_value: this.getColumnFormattedValue(col),
      }) as dynamicObj;
    },

    columnModel(column: any) {
      return {
        id: column.id,
        name: column.name,
        value: column.value,
        formatted_value: column.formatted_value,
      };
    },

    addRowToTableRowObj(rowId: string, columnId: string, column: any) {
      this.tableRowsObj[rowId].columns[column.name] = {};
      const col_class = column.name + '_' + rowId;
      column.formatted_value = this.getColumnFormattedValue(column);
      column['value'] = column.formatted_value;

      Object.assign(this.tableRowsObj[rowId].columns[column.name], {
        id: columnId,
        name: column.name,
        col_class: col_class,
        value: column.value,
        formatted_value: column.formatted_value,
      });

      if (column.highlight_field) {
        column.highlight_field = false;
        this.fieldListToHighlight.push(col_class + '_parent');
      }
    },

    getColumnFormattedValue(column: any) {
      if (!column.formatted_value) {
        column.formatted_value = '';
      }

      if (column.col_type.toLowerCase() == 'boolean') {
        column.formatted_value = Boolean(column.formatted_value);
      }
      return column.formatted_value as string | boolean;
    },

    removeRow(index: number, rowId: string) {
      this.removeEventOnRow(this.tableRowsObj[rowId]);
      this.tableRows.splice(index, 1);
      this.tableRowsObj.splice(index, 1);
      this.formBuilderModel[this.fieldName].rows.splice(index, 1);
    },

    async copyRow(index: number) {
      let rowId = uid();
      let newRow = [] as any;

      for (const item in this.tableRows[index]) {
        newRow[item] = this.tableRows[index][item];
      }
      newRow['id'] = rowId;
      this.tableRows.splice(index + 1, 0, newRow);

      let columnsObj = [] as any;
      this.tableRowsObj[rowId] = [];
      this.tableRowsObj[rowId].columns = [];

      // Store extra column for remove button
      for (let [index, column] of Object.entries(this.tableColumns)) {
        const col = this.getNewColumnObj(column);
        col.formatted_value = newRow[col.name];

        this.addRowToTableRowObj(rowId, col.id, col);
        columnsObj.push(this.columnModel(column));
      }

      const entry = Object.assign({}, { id: rowId, columns: columnsObj });
      this.formBuilderModel[this.fieldName].rows.splice(index + 1, 0, entry);

      for (const column_name in newRow) {
        if (!this.tableRowsObj[rowId]['columns'][column_name]) {
          continue;
        }
        this.inputValueChanges(column_name, rowId);
      }

      await this.$nextTick();
      this.addEventOnRowColumns(rowId, this.tableRowsObj[rowId]);
    },

    async initEventsOnMount() {
      await this.$nextTick();

      let fieldEl: HTMLElement | null = document!.querySelector(
        '.' + this.fieldName,
      );
      if (fieldEl) {
        fieldEl.addEventListener(
          'focus_first_row_column',
          this.focusFirstRowColumn,
        );
        fieldEl.addEventListener('trigger_add_row', this.triggerAddRow);
        fieldEl.addEventListener('keydown', this.handleKeyDown);
      }

      for (let [index, row] of Object.entries(this.tableRowsObj)) {
        this.addEventOnRowColumns(index, row);
      }
    },

    // focus first column of first row
    focusFirstRowColumn(e: any) {
      if (this.tableRows.length === 0) {
        return;
      }
      const first_row = this.tableRows[0];
      if (!first_row) {
        return;
      }

      const first_column = this.tableColumns[0];
      if (!first_column) {
        return;
      }

      const col_class =
        this.tableRowsObj[first_row.id]['columns'][first_column.name].col_class;
      this.focusOnColumn(col_class, first_column.col_type);
    },

    getRowEl(row_id: string) {
      const rowEl: HTMLElement | null = document!.querySelector(
        '#' + this.getRowIdPrefix() + row_id,
      );
      return rowEl;
    },

    addEventOnRowColumns(row_id: string, row: any) {
      try {
        if (!this.hasListOfValuesForAnyColumn()) {
          return;
        }

        const rowEl = this.getRowEl(row_id);
        if (!rowEl) {
          logError('Row el is missing', row_id);
          return;
        }

        if (!row.columns) {
          logError('row is missing columns attribute', row);
          return;
        }

        for (const [column_name, column] of Object.entries(row.columns)) {
          const col = column as any;
          let add_event = true;
          if (col.col_type && col.col_type.toLowerCase() == 'boolean') {
            add_event = false;
          }

          if (add_event && this.lov_columns_mapping[column_name]) {
            this.addEventOnColumn(col.col_class);
          }
        }
      } catch (err) {
        logError(err);
      }
    },

    addEventOnColumn(col_class: string) {
      let inputEl: HTMLInputElement | null = document!.querySelector(
        '.' + col_class,
      );
      if (inputEl) {
        inputEl.addEventListener('update_field_value', this.updateModel);
      }
    },

    removeEventOnRow(row: any) {
      try {
        if (!this.hasListOfValuesForAnyColumn()) {
          return;
        }

        if (!row.columns) {
          logError('row is missing columns attribute', row);
          return;
        }

        for (const [column_name, column] of Object.entries(row.columns)) {
          const col = column as any;
          if (this.lov_columns_mapping[column_name]) {
            this.removeEventOnColumn(col.col_class);
          }
        }
      } catch (err) {
        logError(err);
      }
    },

    removeEventOnColumn(col_class: string) {
      let inputEl: HTMLInputElement | null = document!.querySelector(
        '.' + col_class,
      );
      if (inputEl) {
        inputEl.removeEventListener('update_field_value', this.updateModel);
      }
    },

    updateModel(e: any) {
      try {
        let row_id = String(e.target.closest('tr').getAttribute('id'));
        row_id = row_id.replace(this.getRowIdPrefix(), '');

        const elements = e.target.querySelectorAll('[data-column-name]');
        if (elements.length == 0) {
          return;
        }

        const element = elements[0];
        const column_name = element.getAttribute('data-column-name');
        this.tableRowsObj[row_id]['columns'][column_name].formatted_value =
          e.detail.val;

        this.focusToNextColumn(element);
        this.inputValueChanges(column_name, row_id);
      } catch (err) {
        logError(err);
      }
    },

    getRowIdPrefix() {
      return 'tbl_row_';
    },

    hasTable() {
      if (this.tableColumns.length > 0) {
        this.displayTable = true;
      }
    },

    checkboxUpdateForColumn(column_name: string, rowId: string, val: any) {
      // if (this.is_focus_event) {
      //   this.is_focus_event = false;
      //   return;
      // }
      this.tableRowsObj[rowId]['columns'][column_name].formatted_value = val;
      this.inputValueChanges(column_name, rowId);
    },

    inputValueChanges(column_name: string, rowId: string) {
      const columnValue =
        this.tableRowsObj[rowId]['columns'][column_name].formatted_value;

      const row_index = this.formBuilderModel[this.fieldName].rows.findIndex(
        (row: any) => row.id == rowId,
      );
      if (row_index === -1) {
        return;
      }

      const column_index = this.formBuilderModel[this.fieldName].rows[
        row_index
      ].columns.findIndex((column: any) => column.name == column_name);
      if (column_index === -1) {
        return;
      }

      const old_value =
        this.formBuilderModel[this.fieldName].rows[row_index].columns[
          column_index
        ].formatted_value;
      if (
        !this.formBuilderModel[this.fieldName].rows[row_index].columns[
          column_index
        ].hasOwnProperty('original_value')
      ) {
        this.formBuilderModel[this.fieldName].rows[row_index].columns[
          column_index
        ]['original_value'] = old_value;
      }

      this.formBuilderModel[this.fieldName].rows[row_index].columns[
        column_index
      ].value = columnValue;
      this.formBuilderModel[this.fieldName].rows[row_index].columns[
        column_index
      ].formatted_value = columnValue;

      this.triggerScriptCalculate(column_name, rowId);
    },

    triggerScriptCalculate(columnName: string, rowId: string) {
      if (
        !(
          this.savedColumnsMap.has(columnName) &&
          this.savedColumnsMap.get(columnName).run_script_on_change
        )
      ) {
        return;
      }

      const event = new CustomEvent('script_calculate_func', {
        detail: {
          columnName,
          rowId,
        },
      });
      document.dispatchEvent(event);
    },

    markTableColumns(e: any, columnId: string) {
      setTimeout(() => {
        this.$emit('markTableColumns', columnId + '__' + this.fieldName);
        const event = new CustomEvent('load_settings_for_series', {
          detail: columnId,
        });
        document.dispatchEvent(event);
      }, 100);
    },

    triggerAddRow() {
      this.addRow();
    },

    // keyboard shortcuts
    handleKeyDown(e: any) {
      try {
        // logInfo('handleKeyDown',e);
        switch (e.key) {
          case 'ArrowDown':
            this.moveToNextRowColumn(e);
            e.stopPropagation();
            e.preventDefault();
            break;
          case 'ArrowUp':
            this.moveToPrevRowColumn(e);
            e.stopPropagation();
            e.preventDefault();
            break;
          case 'ArrowRight':
            this.focusToNextColumn(e.target);
            e.stopPropagation();
            e.preventDefault();
            break;
          // case 'Enter':
          //   this.focusToNextColumn(e.target);
          //   e.stopPropagation();
          //   break;
          case 'ArrowLeft':
            this.focusToPrevColumn(e.target);
            e.stopPropagation();
            e.preventDefault();
            break;
        }

        // combKey + Plus
        const combKey = this.isCombinationKey(e);
        const enter_codes = this.getAddRowKeyCodes();
        if (enter_codes.includes(e.keyCode) && combKey === true) {
          this.triggerAddRow();
          e.preventDefault();
          e.stopPropagation();
        }
      } catch (err) {
        logError(err);
      }
    },

    moveToPrevRowColumn(e: any) {
      const current_td = e.target.closest('td');
      if (!current_td) {
        return;
      }

      const column_name = current_td.getAttribute('data-name');
      const prev_tr =
        current_td.closest('tr').previousSibling.previousElementSibling;
      if (!prev_tr) {
        return;
      }
      const prev_td = prev_tr.querySelector(
        "[data-name='" + column_name + "']",
      );
      this.focusOnColumnByTd(prev_td);
    },

    moveToNextRowColumn(e: any) {
      const current_td = e.target.closest('td');
      if (!current_td) {
        return;
      }
      const column_name = current_td.getAttribute('data-name');
      const next_tr = current_td.closest('tr').nextSibling.nextElementSibling;
      if (!next_tr) {
        return;
      }

      const next_td = next_tr.querySelector(
        "[data-name='" + column_name + "']",
      );
      this.focusOnColumnByTd(next_td);
    },

    async focusToPrevColumn(current_input: any) {
      if (!current_input) {
        return;
      }
      await this.$nextTick();

      current_input.blur();
      const current_el = current_input.closest('td');
      const prev_td = current_el.closest('td').previousSibling;
      if (!prev_td) {
        return;
      }

      if (
        typeof prev_td.hasAttribute === 'function' &&
        prev_td.hasAttribute('data-input-class')
      ) {
        this.focusOnColumnByTd(prev_td);
        return;
      }
    },

    async focusToNextColumn(current_input: any) {
      if (!current_input) {
        return;
      }
      await this.$nextTick();

      current_input.blur();
      const current_td = current_input.closest('td');
      const next_td = current_td.nextSibling;
      if (!next_td) {
        return;
      }

      if (
        typeof next_td.hasAttribute === 'function' &&
        next_td.hasAttribute('data-input-class')
      ) {
        this.focusOnColumnByTd(next_td);
        return;
      }
      const next_tr = current_td.closest('tr').nextSibling.nextElementSibling;
      if (!next_tr) {
        return;
      }
      this.focusToRowFirstColumn(next_tr);
    },

    focusToRowFirstColumn(next_tr: any) {
      if (!next_tr) {
        return;
      }

      if (next_tr.children.length == 0) {
        return;
      }

      let first_column;
      for (let child_el of next_tr.children) {
        if (!child_el.dataset.hasOwnProperty('inputClass')) {
          continue;
        }
        first_column = child_el;
        break;
      }
      this.focusOnColumnByTd(first_column);
    },

    focusOnColumnByTd(td_el: any) {
      if (!td_el) {
        return;
      }
      const column_name = td_el.getAttribute('data-name');
      const column_type = td_el.getAttribute('data-type');
      const column_col_class = td_el.getAttribute('data-input-class');
      this.focusOnColumn(column_col_class, column_type);
    },

    focusOnColumn(col_class: string, column_type: string) {
      if (column_type !== 'STRING') {
        this.checkboxFocusHandler(col_class);
        return;
      }
      const parentDiv: HTMLElement | null = document.querySelector(
        '.' + col_class,
      );
      if (!parentDiv) {
        return;
      }
      const input: HTMLElement | null = parentDiv.querySelector('input');
      if (!input) {
        return;
      }
      input.click();
      input.focus();
    },

    checkboxFocusHandler(col_class: string) {
      const parentDiv: HTMLElement | null = document.querySelector(
        '.' + col_class,
      );
      if (!parentDiv) {
        return;
      }
      this.is_focus_event = true;
      parentDiv.focus();
    },

    focusEvent(e: any) {
      this.is_focus_event = true;
      setTimeout(() => {
        this.is_focus_event = false;
      }, 500);
    },

    routeToTableTraining() {
      this.$router.push('/tbl_ext_v3/' + this.$route.params.id);
    },
  },
  setup() {
    let data: any = [];

    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      documentTables,
      docType,
      fieldListToHighlight,
      activeFieldName,
      activeTab,
    } = storeToRefs(form_builder_store);

    const { replaceElementInLayout, getDocumentTables } = form_builder_store;

    const field_values_setting_store = useFieldValuesSettingsStore();
    const { getListOfValues } = field_values_setting_store;

    return {
      getListOfValues,
      formBuilderConfigModel,
      fieldListToHighlight,
      isFormBuilderMode,
      formBuilderModel,
      activeFieldName,
      documentTables,
      activeTab,
      docType,

      tableRows: ref(data),
      tableRowsObj: ref(data),
      tableColumns: ref(data),
      column_properties_map: ref({} as dynamicObj),
      lov_columns_mapping: ref({} as dynamicObj),

      //functions
      getDocumentTables,
      replaceElementInLayout,
      is_focus_event: ref(false),
    };
  },
});
</script>
